package com.bank.review;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SelectionSortDemo {

    private static final Logger log = Logger.getLogger(SelectionSortDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BigDecimal[] balances = {
            new BigDecimal("300000"), new BigDecimal("50000"),
            new BigDecimal("1000000"), new BigDecimal("75000")
        };

        log.info(() -> "Before: " + Arrays.toString(balances));
        new SelectionSorter().sortAscending(balances);
        log.info(() -> "After:  " + Arrays.toString(balances));
    }
}

