class SelectionSorter {

    private static final Logger log = Logger.getLogger(SelectionSorter.class.getName());

    // Sort ascending in place; at most one swap per pass.
    void sortAscending(BigDecimal[] arr) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            // Find the index of the minimum in the unsorted suffix [i..n-1].
            int minIndex = i;
            for (int j = i + 1; j < n; j++) {
                if (arr[j].compareTo(arr[minIndex]) < 0) {
                    minIndex = j;
                }
            }
            // Single swap: bring the minimum to the front of the unsorted region.
            if (minIndex != i) {
                swap(arr, i, minIndex);
            }
            final int pos = i;
            final int mi = minIndex;
            log.info(() -> "Pass " + (pos + 1) + ": placed min "
                    + arr[pos] + " (from index " + mi + ") at position " + pos
                    + " → " + java.util.Arrays.toString(arr));
        }
    }

    private void swap(BigDecimal[] arr, int i, int j) {
        BigDecimal temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
